"""A01C: player/request continuation and ALL resolution, separated from lexer flags."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA01C,0xA01D,'data','Modo della risoluzione: normale0 o iterazione128'),(0xD6B8,0xD6B9,'data','Continuazione semantica del giocatore, distinta dal modo globale'),(0xA040,0xA048,'code','Avvio: reset esplicito D6B8 e chiarimento'),(0x82B1,0x82B9,'data','Modello12 CLIMB INTO: forza un solo referente'),(0x8349,0x8351,'data','Modello31 HAIL: forza un solo referente'),(0xB1DD,0xB213,'code','Ingresso semantico: riuso del modo, flag ALL e azzeramento forzato'),(0xB213,0xB259,'code','Ricerca del primo referente: scelta singola o scansione completa'),(0xB280,0xB2B7,'code','Due argomenti: ricerca delle coppie e riuso del cursore ALL'),(0xB39C,0xB39D,'data','Flag ALL dell’ultimo nodo esaminato: distinto da A01A e A01C'),(0xB39D,0xB3B0,'code','Lettura del verbo: separa bit15 ALL dalla parola lessicale'),(0xB936,0xB98C,'code','Richieste NPC: modo dal record e salvataggio della continuazione'),(0xB9AC,0xB9CA,'code','Fallimento NPC: pulizia diversa per ALL e richiesta normale'),(0xB9CA,0xB9FA,'code','Avanza la richiesta e libera i nodi saltando BUT ed EXCEPT'),(0xD7FC,0xD87D,'code','Giocatore: copia D6B8, risoluzione, trasferimento e rilascio dei nodi')]
notes={0xA01C:'Byte condiviso0/128. Non coincide col lessico A01A0/1/2 né col chiarimento A01B08/12. Conservare il valore fino a uno dei quattro writer D800/B1EC/B1FD/B959.',0xD6B8:'Il giocatore mantiene qui il proprio stato attraverso turni NPC che possono cambiare A01C. A041 lo azzera all’avvio, D81B copia il modo dopo successo, D85C lo azzera su fallimento. Vecchi save assenti restano sconosciuti.',0xA041:'Reset reale della continuazione del giocatore; A01C invece conserva il dato iniziale caricato0 durante l’avvio verificato.',0x82B1:'Record lessicale di8 byte. Il bit4 del modo proiettato in A01E obbliga A01C=0; ALL non trasforma CLIMB INTO in più ingressi successivi.',0x8349:'Stesso bit4 nel modello HAIL: sceglie un referente e non enumera veicoli/oggetti come un ALL ordinario.',0xB1E3:'Con modo già nonzero riusa il cursore precedente: non riinizializzare la ricerca a ogni candidato.',0xB1EC:'Solo con A01C=0 copia il bit ALL del nodo da B39C:0/128. Anche riscrivere0 è un evento reale.',0xB1FD:'Bit4 del modo del modello: azzera incondizionatamente A01C dopo il riconoscimento. Non confondere con A01A, che può ancora indicare ALL nel lexer.',0xB218:'Nel modo normale esegue la conta nominale; con ALL riprende direttamente dal cursore conservato.',0xB23E:'Con ALL si ferma dopo il primo candidato accettabile; in modalità normale continua per scoprire l’ambiguità e porre WHICH.',0xB280:'La coppia richiede la ricerca iniziale di entrambi i nomi soltanto senza continuazione ALL. Il numero dei secondi argomenti non è un semplice prodotto di elenchi indipendenti.',0xB39C:'Solo il bit15 del verbo viene copiato qui. Il suo ruolo è compreso, ma il nuovo runtime non pubblica ancora questo byte come ingresso casuale autonomo.',0xB3A8:'Scrive B39C prima del confronto dei modelli. A01C viene aggiornato solo più avanti, se il modello è stato trovato.',0xB946:'Le affermazioni seguono BA20 prima del writer B959: non aggiungere una scrittura del modo a ogni frase rivolta a un NPC.',0xB959:'Una richiesta sintattica copia A01C dal byte2 del proprio record, non dal contesto del giocatore. Le richieste prefabbricate passano B98C e non attraversano questo writer.',0xB97C:'Conserva il modo della richiesta nel record dopo un passo riuscito; se è0 avanza/rilascia il nodo, se128 lo mantiene per la visita successiva.',0xB9B4:'Fallimento con ALL: azzera il modo nel record e avanza la sintassi; A01C può restare128. La richiesta normale scarta i nodi restanti.',0xB9D4:'Aggiorna il puntatore sintattico della richiesta prima di liberare il nodo corrente. Non eliminare il suffisso della richiesta quando ALL si esaurisce.',0xB9EC:'Bit6 nel byte alto del verbo: i nodi BUT/EXCEPT sono clausole di esclusione, non comandi autonomi. Avanza e libera anche questi nodi prima di riprendere il resolver.',0xD800:'Prima di ogni tentativo semantico del giocatore copia D6B8 in A01C. Errori lessicali e sintattici precedenti non raggiungono questa scrittura.',0xD81B:'Successo semantico: conserva il modo prima dell’esecuzione dell’azione e delle visite NPC. Non ricavarlo dal risultato del corpo dell’azione.',0xD835:'Rilascia il nodo soltanto con D6B8=0; ALL mantiene la stessa allocazione fra azioni e visite NPC.',0xD85C:'Fallimento semantico: D6B8=0. A01C non viene azzerato: ALL esaurito può lasciare128 come residuo globale.',0xD85F:'Il modo globale decide il percorso di fallimento e rilascio. Non riempire entrambi i byte con lo stesso booleano pending.'}
lines=['; Dossier offline: istruzioni riassemblate e dati tipizzati; nessuna CPU nel runtime.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/resolution-mode';root.mkdir(exist_ok=True)
(root/'resolution-mode.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=125 if k=='data' else 96,**({'fields':[['A01C','0/128','Modo semantico condiviso, conservato durante errori precedenti al resolver'],['D6B8 / record richiesta+2','continuazioni distinte','Il giocatore e ogni richiesta NPC conservano separatamente il cursore e il proprio modo']]}if a==0xA01C else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
